    "name": "datacenter-evpn.yaml",
    "text": "# netatlas example: data-center fabric\n#\n# A two-spine / four-leaf fabric. The physical view shows racks and cabling;\n# the logical view shows the eBGP underlay, the EVPN control plane, VXLAN\n# data-plane tunnels (one multipoint VNI), MLAG, and a user-defined protocol\n# (\"srv6\") that is not built in.\n#\n# Note: YAML anchors/aliases are NOT supported by netatlas, so repeated\n# interface lists are written out in full.\nnetatlas: 1\ntitle: FRA1 data-center fabric\ndescription: Spine/leaf fabric with BGP underlay and EVPN/VXLAN overlay.\n\nprotocols:\n  - id: srv6\n    label: SRv6 policy\n    category: tunnel\n    color: \"#e03131\"\n    description: Segment routing over IPv6 (user-defined protocol)\n\ngroups:\n  - id: fra1\n    label: FRA1 data hall 2\n    kind: site\n  - id: rack-a01\n    label: Rack A01 (spines)\n    kind: rack\n    parent: fra1\n  - id: rack-a02\n    label: Rack A02 (compute)\n    kind: rack\n    parent: fra1\n  - id: rack-a03\n    label: Rack A03 (border + compute)\n    kind: rack\n    parent: fra1\n  - id: wan\n    label: WAN\n    kind: provider\n\ndevices:\n  - id: spine1\n    type: switch\n    role: spine\n    tier: 1\n    model: 7280R3\n    group: rack-a01\n    interfaces:\n      - {id: Et1, speed: 100G, media: fiber, ip: 10.1.0.0/31}\n      - {id: Et2, speed: 100G, media: fiber, ip: 10.1.0.2/31}\n      - {id: Et3, speed: 100G, media: fiber, ip: 10.1.0.4/31}\n      - {id: Et4, speed: 100G, media: fiber, ip: 10.1.0.6/31}\n      - {id: Lo0, type: loopback, ip: 10.0.250.1/32}\n  - id: spine2\n    type: switch\n    role: spine\n    tier: 1\n    model: 7280R3\n    group: rack-a01\n    interfaces:\n      - {id: Et1, speed: 100G, media: fiber, ip: 10.1.1.0/31}\n      - {id: Et2, speed: 100G, media: fiber, ip: 10.1.1.2/31}\n      - {id: Et3, speed: 100G, media: fiber, ip: 10.1.1.4/31}\n      - {id: Et4, speed: 100G, media: fiber, ip: 10.1.1.6/31}\n      - {id: Lo0, type: loopback, ip: 10.0.250.2/32}\n\n  - id: leaf1\n    type: switch\n    role: leaf\n    tier: 2\n    group: rack-a02\n    interfaces:\n      - {id: Et49, speed: 100G, media: fiber, ip: 10.1.0.1/31}\n      - {id: Et50, speed: 100G, media: fiber, ip: 10.1.1.1/31}\n      - {id: Et51, speed: 100G, media: dac}\n      - {id: Et1, speed: 25G, media: dac}\n      - {id: Lo0, type: loopback, ip: 10.0.250.11/32}\n      - {id: Vxlan1, type: virtual, description: VTEP 10.0.251.12}\n  - id: leaf2\n    type: switch\n    role: leaf\n    tier: 2\n    group: rack-a02\n    interfaces:\n      - {id: Et49, speed: 100G, media: fiber, ip: 10.1.0.3/31}\n      - {id: Et50, speed: 100G, media: fiber, ip: 10.1.1.3/31}\n      - {id: Et51, speed: 100G, media: dac}\n      - {id: Et1, speed: 25G, media: dac}\n      - {id: Lo0, type: loopback, ip: 10.0.250.12/32}\n      - {id: Vxlan1, type: virtual, description: VTEP 10.0.251.12}\n  - id: leaf3\n    type: switch\n    role: border-leaf\n    tier: 2\n    group: rack-a03\n    interfaces:\n      - {id: Et49, speed: 100G, media: fiber, ip: 10.1.0.5/31}\n      - {id: Et50, speed: 100G, media: fiber, ip: 10.1.1.5/31}\n      - {id: Et1, speed: 25G, media: dac}\n      - {id: Et48, speed: 10G, media: fiber, ip: 100.64.0.2/30}\n      - {id: Lo0, type: loopback, ip: 10.0.250.13/32}\n      - {id: Vxlan1, type: virtual, description: VTEP 10.0.251.13}\n  - id: leaf4\n    type: switch\n    role: leaf\n    tier: 2\n    group: rack-a03\n    interfaces:\n      - {id: Et49, speed: 100G, media: fiber, ip: 10.1.0.7/31}\n      - {id: Et50, speed: 100G, media: fiber, ip: 10.1.1.7/31}\n      - {id: Et1, speed: 25G, media: dac}\n      - {id: Lo0, type: loopback, ip: 10.0.250.14/32}\n      - {id: Vxlan1, type: virtual, description: VTEP 10.0.251.14}\n\n  - id: esx01\n    label: esx01\n    type: server\n    group: rack-a02\n    interfaces:\n      - {id: vmnic0, speed: 25G, media: dac}\n      - {id: vmnic1, speed: 25G, media: dac}\n  - id: esx02\n    label: esx02\n    type: server\n    group: rack-a03\n    interfaces:\n      - {id: vmnic0, speed: 25G, media: dac}\n  - id: k8s01\n    label: k8s01\n    type: server\n    group: rack-a03\n    interfaces:\n      - {id: ens1f0, speed: 25G, media: dac}\n\n  - id: wan-pe\n    label: Carrier PE\n    type: router\n    group: wan\n    interfaces:\n      - {id: xe-0/1/0, speed: 10G, media: fiber, ip: 100.64.0.1/30}\n\nlinks:\n  - {id: s1-l1, a: \"spine1:Et1\", b: \"leaf1:Et49\"}\n  - {id: s1-l2, a: \"spine1:Et2\", b: \"leaf2:Et49\"}\n  - {id: s1-l3, a: \"spine1:Et3\", b: \"leaf3:Et49\"}\n  - {id: s1-l4, a: \"spine1:Et4\", b: \"leaf4:Et49\"}\n  - {id: s2-l1, a: \"spine2:Et1\", b: \"leaf1:Et50\"}\n  - {id: s2-l2, a: \"spine2:Et2\", b: \"leaf2:Et50\"}\n  - {id: s2-l3, a: \"spine2:Et3\", b: \"leaf3:Et50\"}\n  - {id: s2-l4, a: \"spine2:Et4\", b: \"leaf4:Et50\"}\n  - {id: mlag-peer, a: \"leaf1:Et51\", b: \"leaf2:Et51\", cable: DAC 0.5m}\n  - {id: esx01-a, a: \"esx01:vmnic0\", b: \"leaf1:Et1\"}\n  - {id: esx01-b, a: \"esx01:vmnic1\", b: \"leaf2:Et1\"}\n  - {id: esx02-a, a: \"esx02:vmnic0\", b: \"leaf3:Et1\"}\n  - {id: k8s01-a, a: \"k8s01:ens1f0\", b: \"leaf4:Et1\"}\n  - {id: wan-uplink, a: \"leaf3:Et48\", b: \"wan-pe:xe-0/1/0\", cable: \"Cross-connect MMR-2 #118\"}\n\nnetworks:\n  - id: vni-10100\n    label: VNI 10100 (web)\n    kind: vni\n    vlan: 100\n    vrf: tenant-a\n    cidr: 192.168.100.0/24\n    members: [leaf1, leaf2, leaf3, leaf4]\n  - id: vrf-tenant-a\n    label: VRF tenant-a\n    kind: vrf\n    attrs: {l3vni: 50001, route-target: \"65000:50001\"}\n    members: [leaf1, leaf2, leaf3, leaf4]\n\nrelations:\n  # eBGP underlay: one session per fabric link\n  - {id: bgp-s1-l1, protocol: ebgp, endpoints: [\"spine1:Et1\", \"leaf1:Et49\"], over: s1-l1}\n  - {id: bgp-s1-l2, protocol: ebgp, endpoints: [\"spine1:Et2\", \"leaf2:Et49\"], over: s1-l2}\n  - {id: bgp-s1-l3, protocol: ebgp, endpoints: [\"spine1:Et3\", \"leaf3:Et49\"], over: s1-l3}\n  - {id: bgp-s1-l4, protocol: ebgp, endpoints: [\"spine1:Et4\", \"leaf4:Et49\"], over: s1-l4}\n  - {id: bgp-s2-l1, protocol: ebgp, endpoints: [\"spine2:Et1\", \"leaf1:Et50\"], over: s2-l1}\n  - {id: bgp-s2-l2, protocol: ebgp, endpoints: [\"spine2:Et2\", \"leaf2:Et50\"], over: s2-l2}\n  - {id: bgp-s2-l3, protocol: ebgp, endpoints: [\"spine2:Et3\", \"leaf3:Et50\"], over: s2-l3}\n  - {id: bgp-s2-l4, protocol: ebgp, endpoints: [\"spine2:Et4\", \"leaf4:Et50\"], over: s2-l4}\n\n  # EVPN control plane: loopback-to-loopback multihop sessions to the spines\n  - {id: evpn-s1-l1, protocol: evpn, endpoints: [\"spine1:Lo0\", \"leaf1:Lo0\"], over: bgp-s1-l1}\n  - {id: evpn-s1-l3, protocol: evpn, endpoints: [\"spine1:Lo0\", \"leaf3:Lo0\"], over: bgp-s1-l3}\n  - {id: evpn-s2-l2, protocol: evpn, endpoints: [\"spine2:Lo0\", \"leaf2:Lo0\"], over: bgp-s2-l2}\n  - {id: evpn-s2-l4, protocol: evpn, endpoints: [\"spine2:Lo0\", \"leaf4:Lo0\"], over: bgp-s2-l4}\n\n  # VXLAN data plane: one multipoint relation for the VNI (drawn with a hub)\n  - id: vxlan-10100\n    protocol: vxlan\n    label: VNI 10100\n    endpoints: [\"leaf1:Vxlan1\", \"leaf2:Vxlan1\", \"leaf3:Vxlan1\", \"leaf4:Vxlan1\"]\n    network: vni-10100\n    attrs: {vni: 10100, replication: ingress, udp-port: 4789}\n\n  - id: mlag-12\n    protocol: mlag\n    label: MLAG domain 1\n    endpoints:\n      - {device: leaf1, role: primary}\n      - {device: leaf2, role: secondary}\n    over: mlag-peer\n    attrs: {domain-id: 1, peer-address: 10.255.255.2}\n  - id: lacp-esx01\n    protocol: lacp\n    endpoints: [esx01, leaf1, leaf2]\n    over: [esx01-a, esx01-b]\n    attrs: {mode: active}\n\n  - id: srv6-dci\n    protocol: srv6\n    label: DCI policy blue\n    endpoints: [\"leaf3:Lo0\", \"wan-pe\"]\n    over: wan-uplink\n    attrs: {color: 100, endpoint: \"2001:db8:f::1\", segment-list: \"fc00:0:1::, fc00:0:5::\"}\n  - id: ebgp-wan\n    protocol: ebgp\n    endpoints: [\"leaf3:Et48\", \"wan-pe:xe-0/1/0\"]\n    over: wan-uplink\n    attrs: {local-as: 65100, peer-as: 64512}\n"
